function moodleRosterReference(tables,domain){const pupils=[];for(const table of tables){const rows=table.rows,h=rows.findIndex(r=>r.some(v=>/^(correo( electronico)?|direccion (de )?(correo( electronico)?|email)|email|e-mail)$/.test(Aula.norm(v))));if(h<0)continue;const header=rows[h],email=header.findIndex(v=>/^(correo( electronico)?|direccion (de )?(correo( electronico)?|email)|email|e-mail)$/.test(Aula.norm(v))),first=header.findIndex(v=>/^(nombre|nombres|nombre completo)$/.test(Aula.norm(v))),last=header.findIndex(v=>/^(apellido|apellidos|apellido\(s\))$/.test(Aula.norm(v)));for(const row of rows.slice(h+1)){const identity=schoolIdentity(row[email],domain);if(!identity)continue;let name=[row[first]||'',last>=0?row[last]||'':''].filter(Boolean).join(' ').trim();if(last<0&&name.includes(',')){const parts=name.split(',');if(parts.length===2)name=parts[1].trim()+' '+parts[0].trim()}if(!pupils.some(p=>p.email===identity.email&&Aula.norm(p.name)===Aula.norm(name)))pupils.push({...identity,name})}}if(!pupils.length)throw Error('La lista de Moodle no tiene correos escolares válidos reconocibles. Usa una descarga con Dirección de correo electrónico, Nombre y Apellidos.');return pupils}
