let activityAttendanceFilter='alerts',activityAttendanceQuery='';
function activityAttendanceRows(){const index=Aula.index(db),rows=[];for(const a of activities())for(const s of roster(a.groupId)){const sub=index.submissions.get(s.id+'|'+a.id),review=index.reviews.get(s.id+'|'+a.id),mark=s.attendance?.find(m=>m.date===a.classAt),cancelled=db.groups.find(g=>g.id===a.groupId)?.attendanceSessions?.some(x=>x.date===a.classAt&&x.cancelled);let delivery='unknown';if(review?.source==='moodle-zero'&&!(sub?.channel==='email'||sub?.status==='email'))delivery='missing';else if(sub&&['missing','not-delivered'].includes(sub.status))delivery='missing';else if(sub&&['pending','email','late','correction','reviewed'].includes(sub.status))delivery='delivered';else if(review)delivery='delivered';let kind='consistent',message='Asistió y entregó';if(!a.classAt){kind='unknown';message='Falta indicar el día de clase de la actividad'}else if(a.classAt>nowDate()){kind='waiting';message='La fecha de clase aún no llega'}else if(cancelled||academicDayOff(a.classAt)){kind='unknown';message='Día sin clase: no se contrasta'}else if(!mark||!['present','absent','justified'].includes(mark.state)){kind='unknown';message='Sin registro de asistencia para ese día'}else if(delivery==='unknown'){kind='unknown';message='Sin registro de entrega: no se asume que no entregó'}else if(delivery==='missing'&&a.dueAt&&a.dueAt>=nowDate()){kind='waiting';message='Sin entrega, pero aún dentro del plazo'}else if(mark.state==='absent'&&delivery==='delivered'){kind='absent-delivered';message='Entregó, pero no asistió'}else if(mark.state==='present'&&delivery==='missing'){kind='present-missing';message='Asistió, pero no entregó'}else if(mark.state==='justified'){kind=delivery==='delivered'?'justified-delivered':'justified-missing';message=delivery==='delivered'?'Entregó con ausencia justificada':'Ausencia justificada y sin entrega'}else if(mark.state==='absent'&&delivery==='missing'){kind='consistent';message='No asistió y no entregó'}const justification=justificationRecords().find(r=>!r.deletedAt&&r.studentId===s.id&&a.classAt>=r.date&&a.classAt<=(r.endDate||r.date));rows.push({a,s,mark,delivery,kind,message,justification})}return rows}
function renderActivityAttendance(){const states=[{id:'alerts',name:'Diferencias por revisar'},{id:'absent-delivered',name:'Entregó y no asistió'},{id:'present-missing',name:'Asistió y no entregó'},{id:'justified',name:'Ausencias justificadas'},{id:'unknown',name:'Datos por completar'},{id:'waiting',name:'En plazo / fecha futura'},{id:'all',name:'Todos'}];$('content').innerHTML=`<div class="student-filter-bar">${studentSearchControl('activityAttendanceSearch')}<div class="student-filter-field"><label for="activityAttendanceFilter">Resultado del cruce</label><select id="activityAttendanceFilter">${options(states,activityAttendanceFilter)}</select></div><button id="activityAttendanceExport">Exportar comparación</button></div><p class="context-note">Consulta informativa: compara la entrega con el día de clase de cada actividad, no con la fecha límite. No modifica asistencias, justificantes, calificaciones ni penalizaciones. Sin registro de Moodle no significa sin entrega. AJ se muestra por separado y sigue contando para el 80 %.</p><div id="activityAttendanceTable"></div>`;$('activityAttendanceSearch').value=activityAttendanceQuery;function filtered(){const q=Aula.norm(activityAttendanceQuery);return activityAttendanceRows().filter(r=>(!q||matchesStudentSearch(r.s,q)||Aula.norm(r.a.name+' '+r.a.code).includes(q))&&(activityAttendanceFilter==='all'||activityAttendanceFilter==='alerts'&&['absent-delivered','present-missing'].includes(r.kind)||activityAttendanceFilter==='justified'&&r.kind.startsWith('justified-')||r.kind===activityAttendanceFilter))}function table(){const all=activityAttendanceRows(),rows=filtered();$('activityAttendanceTable').innerHTML=`<div class="attendance-overview"><div><strong>${all.filter(r=>r.kind==='absent-delivered').length}</strong><span>Entregó y no asistió</span></div><div><strong>${all.filter(r=>r.kind==='present-missing').length}</strong><span>Asistió y no entregó</span></div><div><strong>${all.filter(r=>r.kind==='unknown').length}</strong><span>Datos por completar</span></div></div><div class="card compact"><h2>Actividades y asistencia · ${rows.length} casos</h2><div class="table-scroll"><table><thead><tr><th>Alumno / actividad</th><th>Día de clase</th><th>Asistencia</th><th>Entrega</th><th>Resultado</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${groupAbove(db.groups.find(g=>g.id===r.s.groupId)?.name)}<strong>${esc(r.s.name)}</strong><small>${esc(r.s.number)} · ${esc(r.a.code)} ${esc(r.a.name)}</small></td><td>${r.a.classAt?justificationDate(r.a.classAt):'Sin fecha'}<small>Límite: ${esc(r.a.dueAt||'Sin fecha')}</small></td><td>${esc({present:'P · Asistió',absent:'AI · No asistió',justified:'AJ · Justificada'}[r.mark?.state]||'Sin registro')}</td><td>${esc({delivered:'Entrega registrada',missing:'Sin entregar registrado',unknown:'Sin registro de entrega'}[r.delivery])}</td><td><span class="attendance-result attendance-result-${['absent-delivered','present-missing'].includes(r.kind)?'without':r.kind==='consistent'?'with':'confirm'}">${esc(r.message)}</span>${r.justification?`<small>Justificante: ${justificationDone(r.justification)?'registrado':'pendiente'} · ${esc(r.justification.notes)}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No hay casos en este filtro. Puedes seleccionar Todos o Datos por completar.</td></tr>'}</tbody></table></div></div>`;initPageSections()}$('activityAttendanceSearch').oninput=()=>{activityAttendanceQuery=$('activityAttendanceSearch').value;table()};$('activityAttendanceFilter').onchange=()=>{activityAttendanceFilter=$('activityAttendanceFilter').value;table()};$('activityAttendanceExport').onclick=()=>{const rows=[['Grupo','ID','Alumno','Actividad','DiaClase','FechaLimite','Asistencia','Entrega','Resultado','Justificante'],...filtered().map(r=>[db.groups.find(g=>g.id===r.s.groupId)?.name||'',r.s.number,r.s.name,r.a.code+' '+r.a.name,r.a.classAt||'',r.a.dueAt||'',r.mark?.mark||'',r.delivery,r.message,r.justification?(justificationDone(r.justification)?'Registrado':'Pendiente'):''])];download(xlsx([['Cruce informativo',rows]]),'ProfeFlow-cruce-asistencia-'+nowDate()+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')};table()}
let participationMode='candidates',participationQuery='',participationMinimum=3;
function participationRows(gid=group,cutoff=nowDate(),minimum=db.settings.consecutiveAbsenceMinimum||3){const pupils=list('students').filter(s=>s.groupId===gid&&s.enrollmentStatus!=='baja'),g=db.groups.find(g=>g.id===gid),cancelled=new Set((g?.attendanceSessions||[]).filter(x=>x.cancelled).map(x=>x.date)),dates=[...new Set([...pupils.flatMap(s=>(s.attendance||[]).filter(m=>['present','absent','justified'].includes(m.state)).map(m=>m.date)),...(g?.attendanceSessions||[]).filter(x=>!x.cancelled).map(x=>x.date)])].filter(d=>d<=cutoff&&!cancelled.has(d)&&!academicDayOff(d)).sort();return pupils.map(s=>{const marks=dates.map(date=>({date,record:s.attendance?.find(m=>m.date===date)})),present=marks.filter(m=>m.record?.state==='present'),absent=marks.filter(m=>m.record?.state==='absent'),justified=marks.filter(m=>m.record?.state==='justified'),unknown=marks.filter(m=>!m.record),pending=justificationRecords().filter(r=>!r.deletedAt&&r.studentId===s.id&&!justificationDone(r));let streak=0;for(const item of [...marks].reverse()){if(item.record?.state!=='absent')break;streak++}const start=streak?dates[dates.length-streak]:'',end=streak?dates.at(-1):'';let initial=0,run=0,longest=0,longestStart='',longestEnd='';for(let i=0;i<marks.length;i++){if(marks[i].record?.state==='absent'){run++;if(run>longest){longest=run;longestStart=dates[i-run+1];longestEnd=dates[i]}}else run=0}for(const m of marks){if(m.record?.state!=='absent')break;initial++}const reasons=longest>=minimum?[longest+' faltas AI consecutivas registradas, del '+longestStart+' al '+longestEnd]:[];return {s,dates,present:present.length,absent:absent.length,justified:justified.length,unknown:unknown.length,streak,start,end,initial,longest,longestStart,longestEnd,pending:pending.length,lastPresent:present.at(-1)?.date||'',reasons,candidate:longest>=minimum}})}
function renderParticipation(){const cutoff=nowDate();participationMinimum=db.settings.consecutiveAbsenceMinimum||3;$('content').innerHTML=`<div class="student-filter-bar">${studentSearchControl('participationSearch')}<div class="student-filter-field"><label for="participationMode">Mostrar</label><select id="participationMode">${options([{id:'candidates',name:'Cualquier racha del semestre'},{id:'initial',name:'Desde el primer día registrado'},{id:'current',name:'Racha actual (últimas clases)'},{id:'all',name:'Todos los alumnos'},{id:'inactive',name:'Inactivos por confirmar baja'}],participationMode)}</select></div><div class="student-filter-field"><label for="participationMinimum">Mínimo de faltas consecutivas</label><input type="number" id="participationMinimum" min="2" max="100" step="1" value="${participationMinimum}"></div><button id="participationExport">Exportar consulta</button></div><p class="context-note">Puedes revisar cualquier racha del semestre, las faltas desde el primer día registrado o solo la racha actual que llega a la última clase registrada. P, AJ o un día sin registro interrumpen la racha; las clases canceladas y futuras no cuentan. Las entregas de Moodle se consultan aparte: no afectan la detección por faltas ni asignan bajas automáticamente.</p><details class="help"><summary>Consultar entregas de Moodle (sin modificar registros)</summary><label for="participationMoodleFile">Subir libro de calificaciones de Moodle</label><input type="file" id="participationMoodleFile" accept=".xlsx,.xls,.csv,.tsv,.html"><p class="muted">Se compara por correo escolar o ID numérico completo. Esta carga es solo una referencia temporal de consulta; no importa notas ni cambia los casos detectados por faltas.</p>${participationMoodleReferences.has(group)?`<p class="muted">${participationMoodleReferences.get(group).matched} alumnos coincidentes · ${participationMoodleReferences.get(group).unmatched} sin coincidencia en este grupo.</p>`:''}</details><div id="participationTable"></div>`;$('participationSearch').value=participationQuery;function filtered(){return participationRows(group,cutoff,participationMinimum).filter(r=>matchesStudentSearch(r.s,Aula.norm(participationQuery))&&(participationMode==='all'?true:participationMode==='inactive'?!!r.s.participationInactive:!r.s.participationInactive&&(participationMode==='initial'?r.initial>=participationMinimum:participationMode==='current'?r.streak>=participationMinimum:r.candidate)))}function table(){const rows=filtered();$('participationTable').innerHTML=`<div class="card compact"><h2>Faltas consecutivas y posibles bajas · ${rows.length} alumnos</h2><div class="table-scroll"><table><thead><tr><th>Alumno</th><th>Racha de faltas</th><th>Asistencia registrada</th><th>Moodle · entregas</th><th>Justificantes</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${groupAbove(db.groups.find(g=>g.id===r.s.groupId)?.name)}<strong>${esc(r.s.name)}</strong><small>${esc(r.s.number)}</small>${r.s.participationInactive?'<span class="attendance-result attendance-result-confirm">Inactivo por confirmar baja</span>':''}</td><td><strong>${participationMode==='initial'?r.initial:participationMode==='current'?r.streak:r.longest} AI consecutivas</strong><small>${participationMode==='initial'?'Desde el primer día registrado':participationMode==='current'?'Racha actual':'Mayor racha registrada'}</small>${r.longest?`<small>${esc(participationMode==='initial'?r.dates[0]:participationMode==='current'?r.start:r.longestStart)} al ${esc(participationMode==='initial'?r.dates[r.initial-1]:participationMode==='current'?r.end:r.longestEnd)}</small>`:''}<small>Racha actual: ${r.streak} · Inicial: ${r.initial}</small></td><td>${r.absent} AI · ${r.present} P · ${r.justified} AJ<small>${r.unknown} días sin registro</small><small>Última P registrada: ${esc(r.lastPresent||'Ninguna')}</small></td><td>${participationMoodleCell(r.s)}</td><td>${r.pending?`<button data-participation-just="${r.s.id}">${r.pending} pendientes</button>`:'Sin pendientes'}${r.s.participationInactiveReason?`<small>Motivo registrado: ${esc(r.s.participationInactiveReason)}</small>`:''}</td><td><button data-participation-status="${r.s.id}">${r.s.participationInactive?'Reactivar alumno':'Marcar inactivo por confirmar'}</button><button data-participation-history="${r.s.id}">Ver historial</button></td></tr>`).join('')||'<tr><td colspan="6">No hay alumnos en este filtro. Puedes consultar Todos los alumnos.</td></tr>'}</tbody></table></div></div>`;bindAll('[data-participation-moodle]',b=>participationMoodleDetail(b.dataset.participationMoodle));bindAll('[data-participation-status]',b=>participationStatusForm(b.dataset.participationStatus));bindAll('[data-participation-just]',b=>openAttendanceJustifications(b.dataset.participationJust));bindAll('[data-participation-history]',b=>{profileId=b.dataset.participationHistory;view='students';render()});initPageSections()}$('participationMoodleFile').onchange=async event=>{try{const reference=parseParticipationMoodle(await readTables(event.target.files[0]),group);participationMoodleReferences.set(group,reference);renderParticipation();toast('Referencia Moodle cargada. No se modificaron notas ni asistencias.')}catch(error){toast(error.message)}};$('participationSearch').oninput=()=>{participationQuery=$('participationSearch').value;table()};$('participationMode').onchange=()=>{participationMode=$('participationMode').value;table()};$('participationMinimum').onchange=async()=>{const n=Number($('participationMinimum').value);if(!Number.isInteger(n)||n<2||n>100){toast('Elige entre 2 y 100 faltas consecutivas.');return}try{await mutate(d=>d.settings.consecutiveAbsenceMinimum=n);participationMinimum=n;table()}catch(error){toast(error.message)}};$('participationExport').onclick=()=>{const rows=[['Grupo','ID','Alumno','Inactivo por confirmar','Mayor racha AI','Inicio mayor racha','Fin mayor racha','AI actuales','AI iniciales','Mínimo configurado','P','AI','AJ','Sin registro','Última P','Justificantes pendientes','Moodle con entrega','Moodle sin enviar','Moodle sin dato','Corte'],...filtered().map(r=>[db.groups.find(g=>g.id===r.s.groupId)?.name||'',r.s.number,r.s.name,r.s.participationInactive?'Sí':'No',r.longest,r.longestStart,r.longestEnd,r.streak,r.initial,participationMinimum,r.present,r.absent,r.justified,r.unknown,r.lastPresent,r.pending,participationMoodleSummary(r.s).delivered,participationMoodleSummary(r.s).missing,participationMoodleSummary(r.s).unknown,cutoff])];download(xlsx([['Faltas consecutivas',rows]]),'ProfeFlow-faltas-consecutivas-'+cutoff+'.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')};table()}

function participationStatusForm(sid){const s=db.students.find(s=>s.id===sid);if(!s)return;const inactive=!!s.participationInactive;dialog(inactive?'Reactivar alumno':'Inactivo por confirmar baja',`<p><strong>${esc(s.name)}</strong> · ${esc(s.number)}</p><p class="muted">${inactive?'Volverá a aparecer en la revisión cotidiana si pertenece al padrón activo.':'Se ocultará de la revisión cotidiana, pero se conservan sus registros, entregas y notas. No equivale a una baja oficial.'}</p><label for="participationReason">Motivo ${inactive?'(opcional)':'(obligatorio)'}</label><textarea id="participationReason" ${inactive?'':'required'}>${esc(inactive?'':s.participationInactiveReason||'')}</textarea>`,async()=>{const reason=$('participationReason').value.trim();if(!inactive&&!reason)throw Error('Escribe el motivo para dejar constancia.');await mutate(d=>{const pupil=d.students.find(p=>p.id===sid);if(!pupil||pupil.trashId)throw Error('Alumno no disponible.');pupil.participationInactive=!inactive;pupil.participationInactiveReason=reason;pupil.participationHistory??=[];pupil.participationHistory.push({date:new Date().toISOString(),inactive:!inactive,reason})});render()},inactive?'Reactivar':'Marcar inactivo')}
// Optional, read-only Moodle reference for the absence report. Never changes grades.
const participationMoodleReferences=new Map();
function parseParticipationMoodle(tables,gid){const people=list('students').filter(s=>s.groupId===gid),records=[],matched=new Set(),unmatched=new Set();let foundColumns=0;for(const table of tables){const h=table.rows.findIndex(r=>r.some(v=>/^(tarea|cuestionario|assignment):/i.test(String(v))));if(h<0)continue;const header=table.rows[h],emailCol=header.findIndex(v=>/^(correo( electronico)?|direccion (de )?(correo( electronico)?|email)|email|e-mail)$/.test(Aula.norm(v))),idCol=header.findIndex(v=>/^(numero de id|id|matricula|numero de control)$/.test(Aula.norm(v))),columns=header.map((v,i)=>({name:String(v).replace(/^[^:]+:/,'').replace(/\s*\(Real\)\s*$/i,'').trim(),i,raw:String(v)})).filter(c=>/^(tarea|cuestionario|assignment):/i.test(c.raw)),seen=new Set();foundColumns+=columns.length;for(const row of table.rows.slice(h+1)){const email=emailCol>=0?String(row[emailCol]||'').trim():'',identity=email?schoolIdentity(email):null,rawId=idCol>=0?String(row[idCol]||'').trim():'',key=identity?.key||(!email&&/^\d+$/.test(rawId)?Aula.idKey(rawId,db.settings.idMatching):'');if(!key){if(row.some(Boolean))unmatched.add(email||rawId||'Sin identificador');continue}if(seen.has(key))throw Error('Hay un ID/correo repetido en Moodle: '+(email||rawId)+'. Revisa la lista.');seen.add(key);const candidates=people.filter(s=>identity&&(s.email||'').toLowerCase()===identity.email||Aula.idKey(s.number,db.settings.idMatching)===key);if(candidates.length!==1){unmatched.add(email||rawId);continue}const pupil=candidates[0];matched.add(pupil.id);for(const col of columns){const value=String(row[col.i]??'').trim(),dash=/^[-–—]$/.test(value),numeric=value!==''?Number(value.replace(',','.')):NaN,state=dash?'delivered':Number.isFinite(numeric)?numeric===0?'missing':numeric>0?'delivered':'unknown':'unknown';records.push({studentId:pupil.id,name:col.name,state,value})}}}if(!foundColumns)throw Error('No hay columnas Tarea: o Cuestionario: en esta lista. Usa el libro de calificaciones de Moodle con correos o IDs completos.');if(!matched.size)throw Error('No hay alumnos coincidentes en este grupo por correo escolar o ID completo. Revisa el grupo de destino.');return {records,matched:matched.size,unmatched:unmatched.size,importedAt:new Date().toISOString()}}
function participationMoodleSummary(s){const reference=participationMoodleReferences.get(s.groupId);let records,source;if(reference){records=reference.records.filter(r=>r.studentId===s.id);source='Archivo de Moodle para consulta'}else{records=[];source='Registros de Moodle ya importados';const index=Aula.index(db);for(const a of list('activities').filter(a=>a.groupId===s.groupId)){const sub=index.submissions.get(s.id+'|'+a.id),review=index.reviews.get(s.id+'|'+a.id);if(sub?.source==='moodle'&&sub.channel!=='email')records.push({studentId:s.id,name:a.code+' '+a.name,state:['missing','not-delivered'].includes(sub.status)?'missing':['pending','reviewed','late','email','correction'].includes(sub.status)?'delivered':'unknown',value:sub.status});else if(review?.source==='moodle-zero')records.push({studentId:s.id,name:a.code+' '+a.name,state:'missing',value:'0'});else if(a.moodleColumn&&index.reviews.get(s.id+'|'+a.id)?.source==='import'){const r=index.reviews.get(s.id+'|'+a.id);records.push({studentId:s.id,name:a.code+' '+a.name,state:r.rawScore>0?'delivered':'unknown',value:String(r.rawScore)})}}}return {records,source,delivered:records.filter(r=>r.state==='delivered').length,missing:records.filter(r=>r.state==='missing').length,unknown:records.filter(r=>r.state==='unknown').length}}
function participationMoodleCell(s){const result=participationMoodleSummary(s);return result.records.length?`<strong>${result.delivered} con entrega registrada</strong><small>${result.missing} sin enviar · ${result.unknown} sin dato</small><button data-participation-moodle="${s.id}">Ver actividades</button>`:'<span class="muted">Sin datos de Moodle para comparar</span>'}
function participationMoodleDetail(sid){const s=db.students.find(s=>s.id===sid);if(!s)return;const result=participationMoodleSummary(s);dialog('Moodle y faltas · consulta',`${groupAbove(db.groups.find(g=>g.id===s.groupId)?.name)}<h3>${esc(s.name)}</h3><p class="muted">${esc(result.source)}. Según tus reglas de importación: guion = entrega pendiente de revisar; 0 = sin enviar; nota mayor que 0 = entrega calificada. Una entrega no prueba asistencia y no reactiva una baja.</p><div class="import-table"><table><thead><tr><th>Actividad de Moodle</th><th>Resultado</th><th>Dato original</th></tr></thead><tbody>${result.records.map(r=>`<tr><td>${esc(r.name)}</td><td>${{delivered:'Tiene entrega registrada',missing:'Sin enviar registrado',unknown:'Sin dato concluyente'}[r.state]}</td><td>${esc(r.value||'Vacío')}</td></tr>`).join('')||'<tr><td colspan="3">Sin datos para este alumno.</td></tr>'}</tbody></table></div><p class="context-note">Solo lectura: no modifica asistencias, faltas, bajas ni calificaciones. La lista descargada no demuestra cuándo se entregó.</p>`,null)}

// A pattern in recorded marks is not proof that the bulk action was used.
function attendanceAllPresentDays(gid,cutoff=nowDate()){
 const pupils=list('students').filter(s=>s.groupId===gid&&inCurrentRoster(s)),g=db.groups.find(g=>g.id===gid);
 if(!pupils.length)return [];
 return attendanceGroupDates(gid,cutoff).filter(date=>pupils.every(s=>s.attendance?.find(m=>m.date===date)?.state==='present')).map(date=>({date,count:pupils.length,verification:g?.attendanceSessions?.find(x=>x.date===date)?.verification||'unknown'}));
}
function attendanceAllPresentCard(gid,cutoff){const days=attendanceAllPresentDays(gid,cutoff);return '<div class="card compact"><h2>Días con todos presentes · '+days.length+'</h2><p class="context-note">Se compara el padrón activo actual del grupo, aunque filtres un alumno. Solo cuenta P: AJ, faltas y registros vacíos descartan el día. Este patrón no confirma que hayas usado Marcar todos P; el padrón histórico puede haber cambiado.</p><div class="table-scroll"><table><thead><tr><th>Día</th><th>Presentes</th><th>Verificación de la lista</th></tr></thead><tbody>'+days.map(d=>'<tr><td>'+justificationDate(d.date)+'</td><td>'+d.count+' / '+d.count+' · P</td><td>'+({unverified:'Asistencia general sin verificar',confirmed:'Lista confirmada',unknown:'Sin información de verificación'}[d.verification])+'</td></tr>').join('')+(days.length?'':'<tr><td colspan="3">No hay días con P para todo el padrón activo hasta este corte.</td></tr>')+'</tbody></table></div></div>'}

// Official attendance only. Exam-turn attendance and justification records never enter here.
function writeOfficialAttendance(student,date,value,source,modifiedAt=new Date().toISOString()){
 const prior=(student.attendance||[]).find(m=>m.date===date),next=value?{...Aula.clone(prior||{}),...Aula.clone(value),date,source}:null;
 if(!prior&&!next)return false;
 if(prior&&next&&prior.state===next.state&&prior.mark===next.mark&&prior.source===next.source)return false;
 student.attendanceHistory??=[];
 student.attendanceHistory.push({date,previous:prior?Aula.clone(prior):null,next:next?Aula.clone(next):null,source,modifiedAt});
 student.attendance=(student.attendance||[]).filter(m=>m.date!==date);
 if(next)student.attendance.push(next);
 return true;
}
function validateOfficialAttendanceHistory(d){for(const s of d.students||[]){if(s.attendanceHistory===undefined)continue;if(!Array.isArray(s.attendanceHistory)||s.attendanceHistory.some(e=>!e||Aula.dateDay(e.date)===null||!['platform-email','manual'].includes(e.source)||!Number.isFinite(Date.parse(e.modifiedAt))||!('previous' in e)||!('next' in e)||[e.previous,e.next].some(v=>v!==null&&(!v||v.date!==e.date||!['present','absent','justified','unknown'].includes(v.state)))))throw Error('Historial de asistencia oficial inválido.')}}
